import argparse

from fastapi import FastAPI, Header, HTTPException, Query
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.rules.time_rules import BusinessTimeError, OffsetError, parse_business_time, parse_offset
from app.store import orders
from app.store.db import connect, migrate

app = FastAPI(title="settlement-ledger")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)
    # 可选：本次收款的业务发生时间（带时区偏移的完整日期时间，到秒）；缺省由服务按当前时间记账。
    business_time: str | None = None

class ReversalIn(BaseModel):
    reversal_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    # 可选：本次冲正的业务发生时间，取值规则与登记收款一致。
    business_time: str | None = None


def _parse_business_time_or_400(value: str | None):
    # 未提供时返回 None，由存储层按当前时间记账；只有显式给值但非法时才返回 400。
    if value is None:
        return None
    try:
        return parse_business_time(value)
    except BusinessTimeError as error:
        raise HTTPException(status_code=400, detail=str(error))

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="", alias=None)) -> dict:
    tenant = x_tenant or ""
    if not tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    business_time = _parse_business_time_or_400(body.business_time)
    try:
        order = orders.add_payment(x_tenant, order_id, body.amount_cents, business_time)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/reversals")
def reverse_payment(order_id: str, body: ReversalIn, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    business_time = _parse_business_time_or_400(body.business_time)
    order, result = orders.reverse_payment(
        x_tenant, order_id, body.reversal_id, body.amount_cents, business_time
    )
    if result == "not_found":
        raise HTTPException(status_code=404, detail="order not found")
    if result == "conflict":
        raise HTTPException(status_code=409, detail="reversal conflicts with current ledger state")
    return order

@app.get("/orders/{order_id}/flow")
def read_order_flow(order_id: str, x_tenant: str = Header(default="")) -> dict:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    flow = orders.list_flow(x_tenant, order_id)
    if flow is None:
        raise HTTPException(status_code=404, detail="order not found")
    return {"order_id": order_id, "entries": flow}

@app.get("/orders/{order_id}/flow/range")
def read_order_flow_range(
    order_id: str,
    x_tenant: str = Header(default=""),
    start: str | None = Query(default=None),
    end: str | None = Query(default=None),
) -> dict:
    # 先做全部入参校验，任一不合法都在读取任何订单/流水数据之前以可区分的参数错误返回。
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    if start is None:
        raise HTTPException(status_code=400, detail="start is required")
    if end is None:
        raise HTTPException(status_code=400, detail="end is required")
    try:
        start_time = parse_business_time(start)
    except BusinessTimeError:
        raise HTTPException(
            status_code=400,
            detail="start must be a complete date-time with timezone offset, precise to the second",
        )
    try:
        end_time = parse_business_time(end)
    except BusinessTimeError:
        raise HTTPException(
            status_code=400,
            detail="end must be a complete date-time with timezone offset, precise to the second",
        )
    if start_time > end_time:
        raise HTTPException(status_code=400, detail="start must not be later than end")
    flow = orders.list_flow_range(x_tenant, order_id, start_time, end_time)
    if flow is None:
        raise HTTPException(status_code=404, detail="order not found")
    return {"order_id": order_id, "entries": flow}

@app.get("/orders/{order_id}/flow/daily-summary")
def read_order_flow_daily_summary(
    order_id: str,
    x_tenant: str = Header(default=""),
    start: str | None = Query(default=None),
    end: str | None = Query(default=None),
    offset: str | None = Query(default=None),
) -> dict:
    # 先做全部入参校验，任一不合法都在读取任何订单/流水数据之前以可区分的参数错误返回。
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    if start is None:
        raise HTTPException(status_code=400, detail="start is required")
    if end is None:
        raise HTTPException(status_code=400, detail="end is required")
    if offset is None:
        raise HTTPException(status_code=400, detail="offset is required")
    try:
        start_time = parse_business_time(start)
    except BusinessTimeError:
        raise HTTPException(
            status_code=400,
            detail="start must be a complete date-time with timezone offset, precise to the second",
        )
    try:
        end_time = parse_business_time(end)
    except BusinessTimeError:
        raise HTTPException(
            status_code=400,
            detail="end must be a complete date-time with timezone offset, precise to the second",
        )
    try:
        zone = parse_offset(offset)
    except OffsetError:
        raise HTTPException(status_code=400, detail="offset must be a timezone offset like +08:00 or Z")
    if start_time > end_time:
        raise HTTPException(status_code=400, detail="start must not be later than end")
    groups = orders.daily_summary(x_tenant, order_id, start_time, end_time, zone)
    if groups is None:
        raise HTTPException(status_code=404, detail="order not found")
    return {"order_id": order_id, "offset": offset, "groups": groups}

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

import re
from datetime import UTC, datetime, timedelta, timezone

# 完整日期时间：年-月-日 时:分:秒，秒为最小精度（不接受仅到分钟、不接受小数秒），
# 且必须带时区偏移（Z 或 ±HH:MM）；历法合法性再交由 datetime.fromisoformat 校验。
_BUSINESS_TIME_RE = re.compile(r"^\d{4}-\d{2}-\d{2}[Tt ]\d{2}:\d{2}:\d{2}(?:Z|[+-]\d{2}:\d{2})$")

# 对账时区偏移：Z 或 ±HH:MM（如 +08:00、-05:00），用于把流水换算到该偏移后按日历日归组。
_OFFSET_RE = re.compile(r"^(?:Z|[+-]\d{2}:\d{2})$")


class BusinessTimeError(ValueError):
    """业务发生时间缺失或不合法。"""


class OffsetError(ValueError):
    """对账时区偏移缺失或不合法。"""


def parse_business_time(value: str | None) -> datetime:
    """把调用方提供的业务发生时间解析为带时区的时间（保留调用方写法所用的时区偏移）。

    取值规则：必须是带时区偏移的完整日期时间、最小精确到秒；非法（缺日期/时间/偏移、
    精度不足、小数秒、历法不存在等）抛 BusinessTimeError。

    返回的 datetime 携带调用方给出的偏移（``Z`` 按 +00:00）；同一时刻的不同写法得到
    相同的 UTC 基准，比较与存储一律先换算到 UTC，不因写法不同而视为不同时刻。
    """
    if not isinstance(value, str) or not _BUSINESS_TIME_RE.match(value):
        raise BusinessTimeError(
            "business_time must be a complete date-time with timezone offset, precise to the second"
        )
    try:
        dt = datetime.fromisoformat(value)
    except ValueError as error:
        raise BusinessTimeError("business_time is not a valid date-time") from error
    if dt.tzinfo is None or dt.microsecond != 0:
        raise BusinessTimeError(
            "business_time must be a complete date-time with timezone offset, precise to the second"
        )
    return dt


def parse_offset(value: str | None) -> timezone:
    """把对账时区偏移文本解析为固定时区（Z 或 ±HH:MM）；非法或缺省抛 OffsetError。"""
    if not isinstance(value, str) or not _OFFSET_RE.match(value):
        raise OffsetError("offset must be a timezone offset like +08:00 or Z")
    text = "00:00" if value == "Z" else value[1:]
    sign = 1 if value == "Z" or value[0] == "+" else -1
    hours, minutes = (int(part) for part in text.split(":"))
    return timezone(sign * timedelta(hours=hours, minutes=minutes))


def offset_minutes(dt: datetime) -> int:
    """该带时区时间相对 UTC 的偏移分钟数（登记时偏移写法的持久化形态）。"""
    return int(dt.utcoffset().total_seconds()) // 60


def timezone_from_minutes(minutes: int) -> timezone:
    """把偏移分钟数还原为固定时区。"""
    return timezone(timedelta(minutes=minutes))


def to_storage(dt: datetime) -> str:
    """落库文本：统一 UTC、到秒、带偏移（如 2026-10-02T08:30:00+00:00）。"""
    return dt.astimezone(UTC).isoformat(timespec="seconds")


def to_display(dt: datetime, offset: timezone) -> str:
    """出参文本：按指定时区偏移渲染、到秒（如 2026-10-02T16:30:00+08:00）。

    时间基准不变，只换写法；同一 UTC 时刻配合登记时偏移即还原登记时的偏移写法。
    """
    return dt.astimezone(offset).isoformat(timespec="seconds")

